declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_login();
if (file_exists(__DIR__ . '/includes/cache.php')) require_once __DIR__ . '/includes/cache.php';
require_once __DIR__ . '/config/database.php';
if (file_exists(__DIR__ . '/includes/csrf.php')) require_once __DIR__ . '/includes/csrf.php';
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');

$userRole = strtolower(trim((string)($_SESSION['user_role'] ?? ($_SESSION['user']['role'] ?? ''))));
if (!in_array($userRole, ['doctor','admin'], true)) {
    http_response_code(403); $pageTitle='Access Restricted | Swasthya Saarathi'; include __DIR__.'/includes/header.php'; ?>
    <style>.access-page{min-height:calc(100vh - 80px);display:grid;place-items:center;padding:40px 18px;background:#f3f9fc}.access-card{width:min(650px,100%);padding:50px 30px;text-align:center;background:#fff;border:1px solid #dcebef;border-radius:26px;box-shadow:0 25px 70px rgba(20,70,100,.12)}.access-card h1{color:#154967}.access-card p{color:#718693;line-height:1.7}.access-btn{display:inline-flex;padding:12px 18px;border-radius:11px;color:#fff;background:linear-gradient(135deg,#0878c5,#00a4a4);text-decoration:none;font-weight:900;font-size:11px}</style>
