function h(mixed $v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
function formatDateTime(?string $v): string { if (!$v) return '—'; $t=strtotime($v); return $t===false?'—':date('d M Y, h:i A',$t); }
function displayStatus(string $v): string { $v=trim($v); return $v===''?'Waiting':ucwords(str_replace(['_','-'],' ',strtolower($v))); }
function statusClass(string $v): string { return 'status-'.preg_replace('/[^a-z0-9_-]/','',strtolower(trim($v))); }
function priorityClass(string $v): string { return 'priority-'.preg_replace('/[^a-z0-9_-]/','',strtolower(trim($v))); }

$search=trim((string)($_GET['search']??''));
$status=strtolower(trim((string)($_GET['status']??'')));
$priority=strtoupper(trim((string)($_GET['priority']??'')));
$page=max(1,(int)($_GET['page']??1)); $perPage=12;
$allowedStatuses=['pending','pending_review','review_pending','under_review','reviewed','completed','referred','closed','waiting'];
$allowedPriorities=['HIGH','MEDIUM','LOW'];
if($status!==''&&!in_array($status,$allowedStatuses,true))$status='';
if($priority!==''&&!in_array($priority,$allowedPriorities,true))$priority='';
$where=[];$params=[];
if($status!==''){ $where[]="LOWER(COALESCE(tr.status,'pending'))=?";$params[]=$status; }
else { $where[]="LOWER(COALESCE(tr.status,'pending')) IN ('pending','pending_review','review_pending','under_review','waiting')"; }
if($priority!==''){ $where[]="UPPER(COALESCE(tr.priority,''))=?";$params[]=$priority; }
if($search!==''){ $where[]='(tr.triage_uid LIKE ? OR p.patient_uid LIKE ? OR p.name LIKE ? OR p.phone LIKE ? OR tr.symptoms LIKE ?)';$s='%'.$search.'%';array_push($params,$s,$s,$s,$s,$s); }
$whereSQL=$where?'WHERE '.implode(' AND ',$where):'';

$stats=['patients'=>0,'cases'=>0,'pending'=>0,'under_review'=>0,'reviewed'=>0,'high'=>0,'medium'=>0,'low'=>0,'with_ocr'=>0,'with_prescription'=>0];
try{
$stats['patients']=(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn();
$stats['cases']=(int)$pdo->query('SELECT COUNT(*) FROM triage_reports')->fetchColumn();
$stats['pending']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE LOWER(COALESCE(status,'pending')) IN ('pending','pending_review','review_pending','waiting')")->fetchColumn();
$stats['under_review']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE LOWER(COALESCE(status,''))='under_review'")->fetchColumn();
$stats['reviewed']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE LOWER(COALESCE(status,'')) IN ('reviewed','completed','closed')")->fetchColumn();
$stats['high']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE UPPER(COALESCE(priority,''))='HIGH'")->fetchColumn();
$stats['medium']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE UPPER(COALESCE(priority,''))='MEDIUM'")->fetchColumn();
$stats['low']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE UPPER(COALESCE(priority,''))='LOW'")->fetchColumn();
$stats['with_ocr']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE (ocr_text IS NOT NULL AND TRIM(ocr_text)<>'') OR (ocr_document_path IS NOT NULL AND TRIM(ocr_document_path)<>'')")->fetchColumn();
$stats['with_prescription']=(int)$pdo->query("SELECT COUNT(*) FROM triage_reports WHERE (prescription_text IS NOT NULL AND TRIM(prescription_text)<>'') OR (prescription_path IS NOT NULL AND TRIM(prescription_path)<>'') OR (medicine_summary IS NOT NULL AND TRIM(medicine_summary)<>'') OR (ocr_medicines IS NOT NULL AND TRIM(ocr_medicines)<>'')")->fetchColumn();
}catch(PDOException $e){}

$totalRecords=0;$cases=[];$totalPages=1;
try{
$c=$pdo->prepare("SELECT COUNT(*) FROM triage_reports tr INNER JOIN patients p ON p.id=tr.patient_id $whereSQL");$c->execute($params);$totalRecords=(int)$c->fetchColumn();$totalPages=max(1,(int)ceil($totalRecords/$perPage));if($page>$totalPages)$page=$totalPages;$offset=($page-1)*$perPage;
$sql="SELECT tr.id,tr.triage_uid,tr.patient_id,tr.symptoms,tr.duration,tr.priority,tr.urgency_flags,tr.missing_information,tr.summary,tr.status,tr.report_path,tr.created_at,tr.ocr_text,tr.prescription_path,tr.medicine_summary,tr.reviewed_by,tr.reviewer_name,tr.reviewed_at,tr.ocr_medicines,tr.ocr_document_path,tr.review_notes,tr.prescription_text,tr.uploaded_document,p.patient_uid,p.name AS patient_name,p.age AS patient_age,p.gender AS patient_gender,p.phone AS patient_phone,p.language AS patient_language,lr.reviewed_at AS latest_review_at,lr.reviewer_name AS latest_reviewer_name,(SELECT COUNT(*) FROM reviews r2 WHERE r2.triage_id=tr.id) AS review_count FROM triage_reports tr INNER JOIN patients p ON p.id=tr.patient_id LEFT JOIN (SELECT r.triage_id,r.reviewed_at,u.name AS reviewer_name FROM reviews r LEFT JOIN users u ON u.id=r.reviewer_id INNER JOIN (SELECT triage_id,MAX(id) max_id FROM reviews GROUP BY triage_id) latest ON latest.max_id=r.id) lr ON lr.triage_id=tr.id $whereSQL ORDER BY CASE WHEN LOWER(COALESCE(tr.status,'pending')) IN ('pending','pending_review','review_pending','waiting') THEN 1 WHEN LOWER(COALESCE(tr.status,''))='under_review' THEN 2 ELSE 3 END,CASE WHEN UPPER(COALESCE(tr.priority,''))='HIGH' THEN 1 WHEN UPPER(COALESCE(tr.priority,''))='MEDIUM' THEN 2 WHEN UPPER(COALESCE(tr.priority,''))='LOW' THEN 3 ELSE 4 END,tr.created_at ASC LIMIT $perPage OFFSET $offset";
$q=$pdo->prepare($sql);$q->execute($params);$cases=$q->fetchAll(PDO::FETCH_ASSOC);
}catch(PDOException $e){$cases=[];}
function queueUrl(array $changes=[]):string{ $q=['search'=>(string)($_GET['search']??''),'status'=>(string)($_GET['status']??''),'priority'=>(string)($_GET['priority']??''),'page'=>1];foreach($changes as $k=>$v)$q[$k]=$v;foreach($q as $k=>$v)if($v===''||$v===null)unset($q[$k]);return 'queue.php'.($q?'?'.http_build_query($q):''); }
$pageTitle='Human Review Queue | Swasthya Saarathi'; include __DIR__.'/includes/header.php';
?>
