<?php foreach($cases as $case):
$cp=strtoupper(trim((string)($case['priority']??'LOW')));if($cp==='')$cp='LOW';$cs=strtolower(trim((string)($case['status']??'pending')));if($cs==='')$cs='pending';
$ocr=trim((string)($case['ocr_text']??''))!==''||trim((string)($case['ocr_document_path']??''))!=='';
$rx=trim((string)($case['prescription_text']??''))!==''||trim((string)($case['prescription_path']??''))!==''||trim((string)($case['medicine_summary']??''))!==''||trim((string)($case['ocr_medicines']??''))!=='';
$rc=(int)($case['review_count']??0);$reviewer=trim((string)($case['latest_reviewer_name']??$case['reviewer_name']??''));$reviewDate=$case['latest_review_at']??$case['reviewed_at']??null;$summary=trim((string)($case['summary']??''));?>
<article class="case-item"><div class="case-main-grid"><div class="case-main"><span class="case-id"><?=h($case['triage_uid']??'TRIAGE CASE')?></span><span class="patient-name"><?=h($case['patient_name']??'Unknown Patient')?></span><span class="patient-uid">Patient UID: <?=h($case['patient_uid']??'—')?></span><?php if($summary!==''):?><span class="case-summary"><?=h($summary)?></span><?php elseif(!empty($case['symptoms'])):?><span class="case-summary"><?=h(trim((string)$case['symptoms']))?></span><?php endif;?></div><div><span class="detail-label">Patient</span><span class="detail-value">Age: <?=h($case['patient_age']??'—')?><?php if(!empty($case['patient_gender'])):?> · <?=h($case['patient_gender'])?><?php endif;?><?php if(!empty($case['patient_language'])):?> · <?=h($case['patient_language'])?><?php endif;?></span><?php if(!empty($case['patient_phone'])):?><span class="detail-value">📞 <?=h($case['patient_phone'])?></span><?php endif;?></div><div><span class="detail-label">Priority</span><span class="priority-pill <?=h(priorityClass($cp))?>"><?=h(ucfirst(strtolower($cp)))?></span></div><div><span class="detail-label">Status</span><span class="status-pill <?=h(statusClass($cs))?>"><?=h(displayStatus($cs))?></span></div><div><span class="detail-label">Records</span><div style="display:flex;gap:5px;flex-wrap:wrap"><?php if($ocr):?><span class="document-pill">OCR</span><?php endif;?><?php if($rx):?><span class="document-pill">Rx</span><?php endif;?><?php if(!$ocr&&!$rx):?><span style="color:#9aa7ae;font-size:8px">No document</span><?php endif;?></div></div></div><div class="case-footer"><div class="case-footer-left"><span class="case-meta">Created: <strong><?=h(formatDateTime($case['created_at']??null))?></strong></span><?php if($rc>0):?><span class="case-meta">• <?=$rc?> review<?=($rc===1?'':'s')?></span><?php endif;?><?php if($reviewer!==''):?><span class="review-info"><span class="review-dot"></span>Reviewed by <strong><?=h($reviewer)?></strong><?php if($reviewDate):?> · <?=h(formatDateTime($reviewDate))?><?php endif;?></span><?php endif;?></div><div class="case-footer-actions"><?php if(!empty($case['report_path'])):?><a href="<?=h($case['report_path'])?>" target="_blank" rel="noopener noreferrer" class="patient-link">📄 Report</a><?php endif;?><?php if($ocr||$rx):?><a href="review.php?id=<?=(int)$case['id']?>" class="patient-link">🔎 Review Data</a><?php endif;?><a href="review.php?id=<?=(int)$case['id']?>" class="review-link">👨‍⚕️ Review →</a></div></div></article>
<?php endforeach;?></div>
